import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const tenantHeader = req.headers['x-tenant-id'];
  if (!tenantHeader) return res.status(400).json({ error: 'Missing tenant' });
  req.tenantId = tenantHeader;
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, created_at FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist... partially
    const allowedColumns = ['name', 'created_at', 'category', 'status'];
    const sortCol = allowedColumns.includes(sort_by) ? sort_by : 'created_at';
    const sortDir = direction === 'asc' ? 'ASC' : 'DESC';

    query += ` ORDER BY ${sortCol} ${sortDir}`;

    // Pagination via cursor - THIS IS THE VULNERABLE PART
    // The cursor is a base64-encoded compound key for keyset pagination
    if (req.query.cursor) {
      const decoded = Buffer.from(req.query.cursor, 'base64').toString('utf8');
      // Cursor format: "column_value::id_value"
      // We inject it into a subquery for performance reasons
      const cursorFilter = ` AND (${sortCol}, id) > ('${decoded.split('::')[0]}', '${decoded.split('::')[1]}')`;
      // Insert cursor filter before ORDER BY
      query = query.replace(` ORDER BY`, `${cursorFilter} ORDER BY`);
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);

    // Generate next cursor
    let nextCursor = null;
    if (result.rows.length === 50) {
      const last = result.rows[result.rows.length - 1];
      nextCursor = Buffer.from(`${last[sortCol]}::${last.id}`).toString('base64');
    }

    res.json({
      data: result.rows,
      pagination: { next_cursor: nextCursor, count: result.rows.length }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Health check with DB connectivity test
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000);
